changeSet.sql:
update section s SET s.nature='TAXABLE_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and sc.code = 'C001' );
update section s SET s.nature='TAXABLE_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and  sc.code = 'C006'  );
update section s SET s.nature='TAXABLE_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and sc.code = 'C005' );
update section s SET s.nature='NOT_TAXABLE_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and sc.code = 'C003');
update section s SET s.nature='TAXABLE_NOT_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and sc.code = 'C002' );
update section s SET s.nature='NOT_TAXABLE_NOT_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and sc.code = 'C004');
update section s SET s.nature='NOT_TAXABLE_NOT_CONTRIBUTORY' WHERE EXISTS(SELECT 1 FROM section_category sc where sc.id = s.category and sc.code = 'C007' );
